package com.manageinvoice.categories;
import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.manageinvoice.common.security.AuthenticatedUser;
@RestController @RequestMapping("/api/v1/categories") public class CategoryController {private final CategoryService service;public CategoryController(CategoryService service){this.service=service;}@GetMapping public List<Category> list(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId){return service.list(workspaceId,user.id());}@PostMapping public Category create(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@RequestBody CategoryService.CreateRequest request){return service.create(workspaceId,user.id(),request);}@PutMapping("/{categoryId}") public Category update(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@PathVariable UUID categoryId,@RequestBody CategoryService.CreateRequest request){return service.update(workspaceId,user.id(),categoryId,request);}@DeleteMapping("/{categoryId}") public org.springframework.http.ResponseEntity<Void> archive(@AuthenticationPrincipal AuthenticatedUser user,@RequestHeader("X-Workspace-Id") UUID workspaceId,@PathVariable UUID categoryId){service.archive(workspaceId,user.id(),categoryId);return org.springframework.http.ResponseEntity.noContent().build();} }
